// catalogsA — CATALOG templates 1–3: Supply Catalog (products + spec tables), Lookbook (fashion),
// Publisher Catalog (cover grid, ISBN/price lines, rights, author storefront).
//
// Catalog pages are built from the same parts a print catalog uses — cards with SKU / price lines, spec tables,
// order forms, an alphabetical index — drawn as editable objects with templateRole SKU / PRICE / SPEC where it
// helps a product feed bind to them.
import type { TelaVectorObject } from '../../../../types';
import type { DesignLesson } from '../types';
import type { PublicationDesigner } from './types';
import { rect, circle, hr, vr, path, text, below, imageSlot, mix, alpha } from '../../templateKit';
import * as orn from '../../ornaments';
import { typeset, cols, figure, pullQuote, table, pill, button, barcode, checkbox, runningFoot, label, verso } from './pubKit';

const obj = (...parts: Array<TelaVectorObject | TelaVectorObject[]>): TelaVectorObject[] => parts.flat();
const stars = (x: number, y: number, n: number, size: number, color: string, empty: string): TelaVectorObject[] => Array.from({ length: 5 }, (_, i) => path(x + i * (size + 3), y, size, size, orn.starPath(5, .42), i < n ? color : empty, { label: 'Rating star' }));

// ═════════════════════════════════════════════════════════════════════════════
// 1 · cat-product — Supply Catalog (Letter; spec-sheet system, orange + ink)
// ═════════════════════════════════════════════════════════════════════════════
