export const DESIGNS_CA: Record<string, PublicationDesigner> = { 'cat-product': supply, 'cat-lookbook': lookbook, 'cat-books': publisher };
export const LESSONS_CA: Record<string, DesignLesson> = {
  'cat-product': { principle: 'A product catalog is a lookup tool before it is a brochure: every item gets a SKU, a price and a spec in the same place, so the eye learns the pattern on page one and never has to relearn it.', history: 'The mail-order catalog began with Aaron Montgomery Ward in 1872 and Richard Sears in the 1890s, whose books taught rural customers to order by number. Industrial catalogs such as McMaster-Carr and the Swiss modernists’ spec sheets later refined the grid of image, code and table that this layout inherits.', tryThis: 'Swap two SKUs and watch how quickly the grid stops being trustworthy. Consistency is the content.', interestTag: 'Catalog design', related: ['Product photography', 'Information design', 'Tables'] },
  'cat-lookbook': { principle: 'A lookbook sells a mood by editing: large plates, look numbers instead of captions, and the business details pushed to the back where buyers will find them.', history: 'Fashion lookbooks grew from the Parisian plates of the nineteenth century and the seasonal books houses sent to buyers, then became art objects in the 1990s when designers such as Margiela and Helmut Lang used plain white covers and grainy photographs. The line sheet and price list remain the working half of the book.', tryThis: 'Replace one full-bleed plate with a smaller image on a wide margin and see how the pacing changes.', interestTag: 'Fashion editorial', related: ['Lookbooks', 'Line sheets', 'Italiana'] },
  'cat-books': { principle: 'A publisher’s catalog gives every book the same three lines, title, author and ISBN with a price, then lets the lead title break the pattern once.', history: 'Trade catalogs descend from the printed booklists of the Aldine Press in Venice and from the Victorian publishers’ announcements bound into the backs of books. Modern seasonal catalogs add the rights page and the metadata that sales reps, booksellers and agents need, and now often link out to author storefronts.', tryThis: 'Remove the covers from the grid and read only the text. If the list still sells the books, the copy is working.', interestTag: 'Book publishing', related: ['ISBN', 'Rights', 'Author storefronts'] },
};
